    # Feature 3: 30-day realised vol of SPY
    spy_daily_ret = spy_c.pct_change().fillna(0)
    f_rvol = spy_daily_ret.rolling(30).std().fillna(spy_daily_ret.std()).values * np.sqrt(252)

